"use client";

import { requestSyncFromExtension } from "@/lib/extensionBridge";
import { useState } from "react";

export default function SyncTimetableButton() {
  const [loading, setLoading] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);

  async function onSync() {
    setLoading(true);
    setMsg(null);

    try {
      // 1) lấy payload từ extension
      const res = await requestSyncFromExtension("timetable");
      if (!res.ok) {
        setMsg(res.error);
        return;
      }

      // 2) forward payload sang Next API route (server) để gọi apps/api
      const upstream = await fetch("/api/import", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(res.payload),
      });

      if (!upstream.ok) {
        const t = await upstream.text();
        setMsg(`Import failed (${upstream.status}): ${t}`);
        return;
      }

      setMsg("Đã đồng bộ xong.");
      window.dispatchEvent(new CustomEvent("mydtu:timetable-updated"));
    } catch (e: any) {
      setMsg(e?.message || "Unknown error");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="flex flex-col items-end">
      <button
        onClick={onSync}
        disabled={loading}
        className="rounded-lg bg-black px-4 py-2 text-white disabled:opacity-60"
      >
        {loading ? "Đang sync..." : "Sync từ Extension"}
      </button>
      {msg ? <div className="mt-2 text-sm opacity-80">{msg}</div> : null}
    </div>
  );
}