"use client";

export type SyncScope = "timetable" | "transcript" | "sections" | "evaluations";

export type ExtensionSyncResponse =
  | { ok: true; payload: unknown }
  | { ok: false; error: string };

function randomId() {
  return Math.random().toString(36).slice(2) + Date.now().toString(36);
}

/**
 * Page -> Extension: window.postMessage({ type: "MYDTU_SYNC_REQUEST", requestId, scope })
 * Extension -> Page: window.postMessage({ type: "MYDTU_SYNC_RESPONSE", requestId, ok, payload|error })
 */
export function requestSyncFromExtension(
  scope: SyncScope,
  timeoutMs = 20_000
): Promise<ExtensionSyncResponse> {
  const requestId = randomId();

  return new Promise((resolve) => {
    let done = false;

    const timer = window.setTimeout(() => {
      if (done) return;
      done = true;
      window.removeEventListener("message", onMessage);
      resolve({ ok: false, error: "Extension did not respond (timeout)." });
    }, timeoutMs);

    const onMessage = (event: MessageEvent) => {
      const data = event.data;
      if (!data || typeof data !== "object") return;
      if (data.type !== "MYDTU_SYNC_RESPONSE") return;
      if (data.requestId !== requestId) return;

      if (done) return;
      done = true;
      window.clearTimeout(timer);
      window.removeEventListener("message", onMessage);

      if (data.ok) resolve({ ok: true, payload: data.payload });
      else resolve({ ok: false, error: data.error || "Unknown error" });
    };

    window.addEventListener("message", onMessage);
    window.postMessage({ type: "MYDTU_SYNC_REQUEST", requestId, scope }, "*");
  });
}