"use client";

import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import SyncTimetableButton from "@/components/SyncTimetableButton";

type TimetableItem = {
  id: string;
  semester: string;
  courseCode: string;
  courseName: string | null;
  dayOfWeek: number;
  startTime: string;
  endTime: string;
  room: string;
  campus: string | null;
  weeksIncluded: string | null;
};

export default function TimetablePage() {
  const { t } = useTranslation();
  const [items, setItems] = useState<TimetableItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  async function load() {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch("/api/timetable", { cache: "no-store" });
      if (!res.ok) {
        setError(await res.text());
        setItems([]);
        return;
      }
      const data = await res.json();
      setItems(data.items || []);
    } catch (e: any) {
      setError(e?.message || "Unknown error");
      setItems([]);
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    load();
    const onUpdated = () => load();
    window.addEventListener("mydtu:timetable-updated", onUpdated);
    return () => window.removeEventListener("mydtu:timetable-updated", onUpdated);
  }, []);

  return (
    <div className="mx-auto w-full max-w-5xl">
      <div className="flex items-start justify-between gap-4">
        <div>
          <h1 className="text-xl font-semibold">{t("timetable.title")}</h1>
          <p className="mt-1 text-sm text-slate-400">{t("timetable.subtitle")}</p>
        </div>
        <div className="flex flex-col items-end">
          <SyncTimetableButton />
          <button onClick={load} className="mt-2 text-sm underline text-slate-300 hover:text-white">
            Tải lại
          </button>
        </div>
      </div>

      <div className="mt-4 rounded-2xl border border-slate-800 bg-slate-950/40 p-4">
        <div className="text-sm font-semibold mb-2">{t("timetable.section")}</div>

        {loading ? (
          <div className="text-sm text-slate-200">Đang tải...</div>
        ) : error ? (
          <div className="text-sm text-red-400">{error}</div>
        ) : items.length === 0 ? (
          <div className="text-sm text-slate-200">
            Chưa có dữ liệu. Bấm “Sync từ Extension” để đồng bộ.
          </div>
        ) : (
          <div className="overflow-auto">
            <table className="min-w-[980px] w-full text-sm">
              <thead>
                <tr className="text-left border-b border-slate-800">
                  <th className="py-2 pr-4">Học kỳ</th>
                  <th className="py-2 pr-4">Thứ</th>
                  <th className="py-2 pr-4">Giờ</th>
                  <th className="py-2 pr-4">Mã môn</th>
                  <th className="py-2 pr-4">Tên môn</th>
                  <th className="py-2 pr-4">Phòng</th>
                  <th className="py-2 pr-4">Cơ sở</th>
                  <th className="py-2 pr-4">Tuần học</th>
                </tr>
              </thead>
              <tbody>
                {items.map((it) => (
                  <tr key={it.id} className="border-b border-slate-900 last:border-b-0">
                    <td className="py-2 pr-4 whitespace-nowrap">{it.semester}</td>
                    <td className="py-2 pr-4 whitespace-nowrap">{toThu(it.dayOfWeek)}</td>
                    <td className="py-2 pr-4 whitespace-nowrap">
                      {it.startTime} - {it.endTime}
                    </td>
                    <td className="py-2 pr-4 whitespace-nowrap">{it.courseCode}</td>
                    <td className="py-2 pr-4">{it.courseName || ""}</td>
                    <td className="py-2 pr-4 whitespace-nowrap">{it.room}</td>
                    <td className="py-2 pr-4 whitespace-nowrap">{it.campus || ""}</td>
                    <td className="py-2 pr-4 whitespace-nowrap">{it.weeksIncluded || ""}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

function toThu(dayOfWeek: number) {
  const map: Record<number, string> = {
    1: "Thứ 2",
    2: "Thứ 3",
    3: "Thứ 4",
    4: "Thứ 5",
    5: "Thứ 6",
    6: "Thứ 7",
    7: "CN",
  };
  return map[dayOfWeek] || `(${dayOfWeek})`;
}